type Toast = { id:number; text:string; kind:'ok'|'error' };
async function api(action:string, args:any){ const res=await fetch("actions",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,args})}); const j=await res.json().catch(()=>({})); if(!res.ok||j.error) throw new Error(j.error||`Request failed (${res.status})`); return j.data; }
