const fmt=(n:number)=> n>=1000 ? (n/1000).toFixed(1).replace('.0','')+'K' : String(n);
const platformColor=(p:string)=> p==='YouTube'?'#FF0000':p==='Twitch'?'#9146FF':p==='Discord'?'#5865F2':p==='X'?'#111111':p==='TikTok'?'#00D4FF':p==='Kick'?'#53FC18':p==='Instagram'?'#E1306C':p==='Facebook'?'#1877F2':p==='Google'?'#4285F4':p==='Apple'?'#111111':p==='Outlook'?'#0072C6':'#A1A1AA';
const avatarColors=['#9146FF','#00D4FF','#FF6B35','#22C55E','#E1306C','#F59E0B','#5865F2','#EC4899'];
const avatarFor=(n:string)=>avatarColors[(n||'?').split('').reduce((a,c)=>a+c.charCodeAt(0),0)%avatarColors.length];
const initials=(n:string)=>(n||'?').trim().split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase();
