/* ---------- SVG LOGOS ---------- */
function StreamSyncLogo({size=36}:{size?:number}){ return <svg width={size} height={size} viewBox="0 0 48 48" aria-label="StreamSync logo"><defs><linearGradient id="ssg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#9146FF"/><stop offset="1" stopColor="#00D4FF"/></linearGradient></defs><rect width="48" height="48" rx="12" fill="url(#ssg)"/><path d="M28 8 L16 27 h8 l-2 13 13-20 h-8 l1-12z" fill="#fff"/></svg>; }
