  if(p==='Twitch') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#9146FF"/><path d="M14 10h20l-3 6v16h-6l-4 4h-3v-4H14V10zm8 8h4v7h-4v-7zm8 0h4v7h-4v-7z" fill="#fff"/></svg>;
  if(p==='Discord') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#5865F2"/><circle cx="18" cy="26" r="4" fill="#fff"/><circle cx="30" cy="26" r="4" fill="#fff"/><path d="M15 17c3-2 6-3 9-3s6 1 9 3c2 4 3 8 3 12-3 2-6 3-9 3s-6-1-9-3c0-4 1-8 3-12z" fill="none" stroke="#fff" strokeWidth="2"/></svg>;
  if(p==='TikTok') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#111"/><path d="M28 10v18a5 5 0 1 1-5-5v-4a9 9 0 1 0 9 9V10h-4z" fill="#fff"/><path d="M28 10v5h4v-5h-4z" fill="#00F2EA"/><circle cx="23" cy="28" r="3" fill="#FE2C55"/></svg>;
  if(p==='X') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#000" stroke="#333"/><path d="M14 12l20 24M34 12L14 36" stroke="#fff" strokeWidth="4" strokeLinecap="round"/></svg>;
  if(p==='Instagram') return <svg width={s} height={s} viewBox="0 0 48 48"><defs><linearGradient id="ig" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F58529"/><stop offset=".5" stopColor="#DD2A7B"/><stop offset="1" stopColor="#8134AF"/></linearGradient></defs><rect width="48" height="48" rx="10" fill="url(#ig)"/><rect x="12" y="12" width="24" height="24" rx="6" fill="none" stroke="#fff" strokeWidth="3"/><circle cx="24" cy="24" r="5" fill="none" stroke="#fff" strokeWidth="3"/><circle cx="31" cy="17" r="2" fill="#fff"/></svg>;
  if(p==='Facebook') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#1877F2"/><path d="M28 12h-3c-3 0-5 2-5 5v4h-4v6h4v11h6V27h5l1-6h-6v-3c0-1 1-2 2-2h4v-4z" fill="#fff"/></svg>;
  if(p==='Google') return <svg width={s} height={s} viewBox="0 0 48 48"><circle cx="24" cy="24" r="22" fill="#fff"/><path d="M24 14c3 0 5 1 7 3l-3 4c-1-1-2-1-4-1-3 0-6 3-6 7s3 7 6 7c3 0 5-2 5-4h-5v-4h10c0 6-4 10-10 10-6 0-11-5-11-11s5-11 11-11z" fill="#4285F4"/><path d="M14 18l3 4c1-2 3-3 6-3 1 0 2 0 3 1l3-4C27 15 25 14 24 14c-5 0-9 2-10 4z" fill="#EA4335"/></svg>;
  if(p==='Apple') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#111"/><path d="M27 11c1 2 0 4-1 5-2-1-3-3-2-5zM24 15c-4 0-8 3-8 9 0 6 4 12 7 12 1 0 2-1 3-1s2 1 3 1c3 0 6-5 7-11-3-1-6-3-6-7-1 1-3 0-6-3z" fill="#fff"/></svg>;
  if(p==='Kick') return <svg width={s} height={s} viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#53FC18"/><path d="M16 12v24M16 24l8-12M16 24l10 12" stroke="#000" strokeWidth="4" strokeLinecap="round"/></svg>;
  if(p==='Google Calendar') return <svg width={s} height={s} viewBox="0 0 48 48"><rect x="6" y="10" width="36" height="32" rx="6" fill="#fff" stroke="#4285F4" strokeWidth="2"/><rect x="6" y="10" width="36" height="9" rx="4" fill="#4285F4"/><text x="24" y="35" textAnchor="middle" fontSize="14" fontWeight="700" fill="#111">31</text></svg>;
  if(p==='Apple Calendar') return <svg width={s} height={s} viewBox="0 0 48 48"><rect x="6" y="10" width="36" height="32" rx="6" fill="#fff" stroke="#111" strokeWidth="2"/><text x="24" y="35" textAnchor="middle" fontSize="14" fontWeight="700" fill="#E1306C">31</text></svg>;
