 useEffect(()=>{ if(view!=='Unified Chat') return; const t=setInterval(()=>{ const pool=[{platform:'Twitch',user:'glowup_greg',text:'Just followed, this is my new favorite stream'},{platform:'YouTube',user:'PriyaP',text:'The lighting upgrade is real'},{platform:'Kick',user:'atlas',text:'LIVE and looking sharp'}]; const m=pool[Math.floor(Math.random()*pool.length)]; setChat(c=>[...c.slice(-45),{...m,time:'now'}]); },9000); return ()=>clearInterval(t); },[view]);
