 useEffect(()=>{ if(view==='Unified Chat') setUnreadChat(0); },[view]);
 useEffect(()=>{ if(!autoTags) return; const words=[...new Set((streamTitle+' '+category).toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/\s+/).filter(w=>w.length>2))].slice(0,5); setAiTags(words.map(w=>'#'+w)); },[streamTitle,category,autoTags]);
 useEffect(()=>{ const onKey=(e:KeyboardEvent)=>{ if(e.key==='Escape'){ setOauthStep(null); setDisconnectPlatform(null); setProfileModal(false); setProfileMenu(false); setSidebar(false); setSearchOpen(false); setNotifOpen(false); setOverlayModal(false); setCalModal(false); setDashModal(null); setDmUser(null); setEndConfirm(false); } }; window.addEventListener('keydown',onKey); return ()=>window.removeEventListener('keydown',onKey); },[]);

 const goTo=(v:string)=>{ if(v===view) return; scrollPos.current[view]=window.scrollY; setView(v); setSidebar(false); setProfileMenu(false); setNotifOpen(false); setSearchOpen(false); setPageLoading(true); setTimeout(()=>{ setPageLoading(false); window.scrollTo(0,scrollPos.current[v]||0); },450); };
 const clock=`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
 const channelNames=[...defaultChannels,...channels.map(c=>c.value.name)].filter((v,i,a)=>a.indexOf(v)===i);
 const communityFeed=[...defaultCommunity.map((x,i)=>({id:'demo-'+i,value:x})),...community].filter(x=>x.value.channel===activeChannel).sort((a,b)=>{ const pa=pinnedByChannel[activeChannel]===a.id?0:1; const pb=pinnedByChannel[activeChannel]===b.id?0:1; return pa-pb; });
 const allPosts=[...savedPosts.map((r:any)=>({id:r.id,title:r.value.title,platforms:[r.value.platform],views:r.value.views||0,status:r.value.status,date:r.value.date,time:r.value.time,description:r.value.description})),...demoPosts.map((p,i)=>({id:'demo-'+i,...p,date:'2026-06-05',time:'18:00'}))];
 const connectedCount=Object.values(connected).filter(Boolean).length;
